"""Parse a raw row (all strings) into a typed record.

The incoming rows look like:
    {"user_id": "42", "score": "9.5", "tags": "a, b ,c"}

parse_row should return:
    {"id": 42, "score": 9.5, "tags": ["a", "b", "c"]}
"""


class PipelineError(Exception):
    """Raised when a row cannot be parsed."""


def parse_row(raw):
    try:
        return {
            "id": int(raw["id"]),
            "score": float(raw["score"]),
            "tags": [t.strip() for t in raw["tags"].split(",")],
        }
    except (KeyError, ValueError) as exc:
        raise PipelineError("failed to parse row") from exc


def run(row):
    return parse_row(row)

