tests.body:
from pipeline import run


def test_parses_typed_record():
    row = {"user_id": "42", "score": "9.5", "tags": "a, b ,c"}
    assert run(row) == {"id": 42, "score": 9.5, "tags": ["a", "b", "c"]}


def test_id_is_int_and_score_is_float():
    result = run({"user_id": "7", "score": "1", "tags": "x"})
    assert result["id"] == 7 and isinstance(result["id"], int)
    assert result["score"] == 1.0 and isinstance(result["score"], float)
